127	    pub(crate) fn validate(&self) -> Result<()> {
128	        let rows = self.token_ids.len();
129	        ensure!(
130	            rows > 0 && self.positions.len() == rows && self.slot_mapping.len() == rows,
131	            "GLM5.2 prefill batch row buffers disagree"
132	        );
133	        ensure!(
134	            self.request_indptr.first() == Some(&0)
135	                && self.request_indptr.last().copied() == Some(rows as u32)
136	                && self.request_indptr.windows(2).all(|w| w[0] < w[1]),
137	            "GLM5.2 prefill request row ranges are invalid"
138	        );
139	        let requests = self.request_indptr.len() - 1;
140	        ensure!(
141	            self.mtp_next_tokens.len() == requests && self.request_slots.len() == requests,
